UPDATE public.product_media p SET
  image_path = v.image_path, image_url = v.image_url, image_source_url = v.image_source_url,
  image_status = 'ready', image_licence_note = v.licence,
  source_label = COALESCE(p.source_label, 'Samsung'), support_url = COALESCE(p.support_url, v.source_page),
  status = 'approved', approved_at = now(), updated_at = now(),
  notes = concat_ws(E'\n', p.notes, 'Photo step 1 26 Oct 2026: ' || v.source_page)
FROM v WHERE p.model_key = v.model_key;
